if(!exists('selection_bias_sensitivity'))library(creditratingsystem)
p<-system.file('examples','selection_transport.R',package='creditratingsystem');if(!nzchar(p))p<-'creditratingsystem-r/examples/selection_transport.R';source(p)
target<-list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='potential_own_contract')
fit<-fit_binary_glm(matrix(numeric(),nrow=4,ncol=0),c(0,1,0,1),feature_order=character(),link='logit',fit_intercept=TRUE,target=target,training=list(data_fingerprint='independent2018four-observations',known_at='2019-01-01',split_id='prior-training',data_origin='SYNTHETIC'),model_id='prior',model_version='1')
pd<-predict_pd(fit,matrix(numeric(),nrow=1,ncol=0),feature_order=character(),expected_target=target)$value[[1]];stopifnot(abs(pd-.5)<1e-12)
records<-lapply(0:3,function(i)list(application_id=as.character(i),customer_id=paste0('customer-',i),facility_id=if(i<2)paste0('loan-',i)else NULL,application_at='2024-01-01',decision_at='2024-01-01',first_draw_at=if(i<2)'2024-01-02'else NULL,funded=i<2,observed=i<2,outcome=if(i<2)i else NULL,offered=i!=2,policy_version='1',pd=pd))
kw<-list(product='own-data',records=records,target=target,model=fit$model,calibrator=NULL,training_entities=as.list(paste0('old',0:3)),cutoff='2024-02-02',assumptions=list(observation_propensity=.5,log_odds_shifts=list(-1,0,1),reference='Explicit scenario'))
o<-do.call(st_audit,kw);s<-o$summary;stopifnot(s$bounds$lower==.25,s$bounds$upper==.75,s$brier==.25,s$mar_effective_sample_size==2,s$mnar_population_pd[[2]]$population_pd==.5,s$stage_counts$funded_observed==2,s$stage_counts$rejected==1,s$stage_counts$offered_not_taken_up==1,!s$pseudo_labels_change_factual_count,s$zero_support_status=='NOT_IDENTIFIED_ZERO_SUPPORT')
bad<-kw;bad$records[[3]]$observed<-TRUE;bad$records[[3]]$outcome<-0;stopifnot(inherits(try(do.call(st_audit,bad),silent=TRUE),'try-error'));bad<-kw;bad$model$training$known_at<-'2024-03-01';stopifnot(inherits(try(do.call(st_audit,bad),silent=TRUE),'try-error'));args<-o$validation_inputs;args$selection_results[[2]]$result$lower<-0;stopifnot(do.call(selection_bias_sensitivity,args)$value$decision$status=='BLOCKED')
